int count(std::vector<int> arr, int n)
{
    // Struct to represent the state of each recursive call frame
    struct Frame {
        int n;
        int i;
        int ans;
        bool returning;
    };

    std::stack<Frame> st;
    st.push({n, 0, 0, false});
    int final_ans = 0;

    while (!st.empty()) {
        Frame& curr = st.top();

        if (curr.returning) {
            // We are returning a value to the caller
            int ret_val = curr.ans;
            st.pop();
            if (st.empty()) {
                final_ans = ret_val;
            } else {
                st.top().ans += ret_val;
                // Complete the backtrack swap for the previous frame's loop iteration
                Frame& parent = st.top();
                swap(arr[parent.i], arr[parent.n - 1]);
                parent.i++; // Move to next iteration
            }
            continue;
        }

        if (curr.n <= 0) {
            curr.ans = 1;
            curr.returning = true;
            continue;
        }

        if (curr.i < curr.n) {
            int i = curr.i;
            int curr_n = curr.n;
            if (arr[i] % curr_n == 0 || curr_n % arr[i] == 0) {
                swap(arr[i], arr[curr_n - 1]);
                // Push new frame for the recursive call
                st.push({curr_n - 1, 0, 0, false});
            } else {
                curr.i++;
            }
        } else {
            // Loop finished, time to return accumulated ans
            curr.returning = true;
        }
    }

    return final_ans;
}

