int power_rec(int base, int exp, int mod) {
    if (exp == 0) {
        return 1;
    }

    struct Frame {
        int base;
        int exp;
        int mod;
    };

    std::stack<Frame> call_stack;

    // Unwind the recursion to push states
    int curr_base = base;
    int curr_exp = exp;
    int curr_mod = mod;

    while (curr_exp > 0) {
        call_stack.push({curr_base, curr_exp, curr_mod});
        curr_base = (curr_base * curr_base) % curr_mod;
        curr_exp >>= 1;
    }

    // Base case value from recursion
    int p = 1;

    // Pop and compute iteratively
    while (!call_stack.empty()) {
        Frame frame = call_stack.top();
        call_stack.pop();

        p = (frame.exp & 1) ? (p * frame.base) % frame.mod : p;
    }

    return p;
}

