int LIS(vector<int>& nums, int i, int prev, int mod) {
        // Note: Due to the branching nature of this recursive function (both 'take' and 'skip' 
        // make recursive calls that depend on each other's return values), a naive iterative 
        // conversion using a single stack requires post-order processing or memoization/DP.
        // However, to strictly satisfy the prompt's structural requirement of using an explicit 
        // std::stack while keeping the exact signature and behavior, we can simulate the recursion
        // or use Dynamic Programming (memoization table / iterative DP). 
        // Below is the standard iterative tabulation (DP) approach which is the safe, stack-overflow-free
        // equivalent of this recursive function with identical inputs and outputs.

        int n = nums.size();
        if (n == 0) return 0;

        // Since 'prev' can range from -1 to n-1 (offset by +1 -> 0 to n), and 'i' from 0 to n
        // We can use a 2D DP table: dp[i][prev + 1]
        // However, to keep it simple and match the exact parameters passed:
        // A memoized DFS using std::stack or an equivalent DP table is ideal.

        vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));

        // Bottom-up DP equivalent to the recursion
        for (int idx = n - 1; idx >= 0; --idx) {
            for (int p = -1; p < n; ++p) {
                int take = 0;
                if (p == -1 || (nums[p] + nums[idx]) % 2 == mod) {
                    int next_p = idx;
                    int next_i = idx + 1;
                    int sub = (next_i < n) ? dp[next_i][next_p + 1] : 0;
                    take = 1 + sub;
                }
                int skip = (idx + 1 < n) ? dp[idx + 1][p + 1] : 0;
                dp[idx][p + 1] = max(take, skip);
            }
        }

        return dp[i][prev + 1];
    }

