double power(double x, int n) {
    if (n == 0) return 1.0;
    if (n == 1) return x;

    // Using a stack to simulate the call stack of the divide-and-conquer approach.
    // We store the exponent 'n' for each step.
    std::stack<int> call_stack;
    int current_n = n;
    while (current_n != 0 && current_n != 1 && current_n != -1) {
        call_stack.push(current_n);
        current_n /= 2;
    }

    // Base case value
    double ans = 1.0;
    if (current_n == 0) {
        ans = 1.0;
    } else if (current_n == 1 || current_n == -1) {
        // For negative base cases, handle appropriately
        ans = (current_n > 0) ? x : (1.0 / x);
    }

    // Unwind the stack and apply the recursive combination logic
    while (!call_stack.empty()) {
        int original_n = call_stack.top();
        call_stack.pop();

        if (original_n % 2 == 0) {
            ans = ans * ans;
        } else if (original_n < 0) {
            ans = ans * ans / x;
        } else {
            ans = ans * ans * x;
        }
    }

    return ans;
}

