int gcd(int x, int y) {
    // Using a stack to simulate the recursive calls
    std::pair<int, int> current;

    // Initial setup mimicking the first step
    if (x < y) std::swap(x, y);
    if (x % y == 0) return y;

    std::stack<std::pair<int, int>> call_stack;
    call_stack.push({y, x % y});

    int result = y;

    while (!call_stack.empty()) {
        current = call_stack.top();
        call_stack.pop();

        int a = current.first;
        int b = current.second;

        if (b == 0) {
            result = a;
            break;
        }

        if (a % b == 0) {
            result = b;
            break;
        }

        // Push the parameters for the next simulated recursive call
        call_stack.push({b, a % b});
    }

    return result;
}

