#include <stack>
#include <cmath>

using namespace std;

long long a[65] = {0};

long long Count(int start_i) {
    if (start_i == 0) return 1;
    if (start_i < 0) return 0;
    if (a[start_i] != 0) return a[start_i];

    stack<int> s;
    s.push(start_i);

    while (!s.empty()) {
        int i = s.top();

        if (i == 0) {
            s.pop();
            continue;
        }
        if (i < 0) {
            s.pop();
            continue;
        }
        if (a[i] != 0) {
            s.pop();
            continue;
        }

        // Check if child (i-1) is already computed
        if (a[i - 1] != 0 || (i - 1) <= 0) {
            long long val_sub = (i - 1 == 0) ? 1 : ((i - 1 < 0) ? 0 : a[i - 1]);
            a[i] = (i + 1) + 2 * val_sub;
            s.pop();
        } else {
            // Push child to be computed first
            s.push(i - 1);
        }
    }

    return a[start_i];
}

long long solve(long long n) {
    long long i, sum = 0;
    while (n > 0) {
        i = log2(n);
        n = n - pow(2, i);
        sum = sum + (i + 1) + Count(i - 1);
    }
    return sum;
}

