#include <stack>

long long Gcd(long long x, long long y) {
  enum Operation { DIRECT, SHIFT, SUBTRACT };

  struct Frame {
    long long x;
    long long y;
    Operation op;
    int shift_count;
  };

  std::stack<Frame> call_stack;
  call_stack.push({x, y, DIRECT, 0});

  long long result = 0;
  bool has_result = false;

  while (!call_stack.empty()) {
    Frame current = call_stack.top();
    call_stack.pop();

    long long cx = current.x;
    long long cy = current.y;

    if (current.op == SHIFT) {
      result <<= current.shift_count;
      has_result = true;
      continue;
    } else if (current.op == SUBTRACT) {
      // The result of the recursive call (cx, cy - cx) is now in 'result'
      has_result = true;
      continue;
    }

    // Evaluating the conditions identically to the recursive version
    if (cx > cy) {
      call_stack.push({cy, cx, DIRECT, 0});
    } else if (cx == 0) {
      result = cy;
      has_result = true;
    } else if (!(cx & 1) && !(cy & 1)) {
      call_stack.push({cx, cy, SHIFT, 1});
      call_stack.push({cx >> 1, cy >> 1, DIRECT, 0});
    } else if (!(cx & 1) && cy & 1) {
      call_stack.push({cx >> 1, cy, DIRECT, 0});
    } else if (cx & 1 && !(cy & 1)) {
      call_stack.push({cx, cy >> 1, DIRECT, 0});
    } else {
      call_stack.push({cx, cy, SUBTRACT, 0});
      call_stack.push({cx, cy - cx, DIRECT, 0});
    }
  }

  return result;
}

