    for (size_t i = 0; i < c.size(); i++) ans += c[i] * mul;
}

void subsetGen(int* arr, int i, int n, int& ans, vector<int>& c) {
    struct Frame {
        int index;
        bool second_branch;
    };

    stack<Frame> st;
    st.push({i, false});

    while (!st.empty()) {
        Frame& curr = st.top();

        if (curr.index == n) {
            subsetSum(c, ans);
            st.pop();
            continue;
        }

        if (!curr.second_branch) {
            curr.second_branch = true;
            st.push({curr.index + 1, false});
        } else {
            c.push_back(arr[curr.index]);
            // We need a helper to pop after the second branch completes.
            // Instead of a complex state machine, let's use a cleaner iterative stack approach below.
        }
    }
