    int current = n;
    while (current > 1) {
        s.push(current);
        current -= 2;
    }

    // Base value at the bottom of the stack
    int result = (current == 0) ? 1 : 0;

    // Unwind the stack and compute iteratively
    while (!s.empty()) {
        int val = s.top();
        s.pop();
        result = -2 * (val - 1) * result;
    }

    return result;
}

