int dfs(std::string& s, int l, int r) {
    int total_swaps = 0;
    std::stack<std::pair<int, int>> st;
    st.push({l, r});

    while (!st.empty()) {
        auto [curr_l, curr_r] = st.top();
        st.pop();

        if (curr_l >= curr_r) continue;

        if (s[curr_l] == s[curr_r]) {
            st.push({curr_l + 1, curr_r - 1});
            continue;
        }

        int front_pos, tail_pos;
        int front_swaps = 0, tail_swaps = 0;

        for (front_pos = curr_l; front_pos <= curr_r && s[front_pos] != s[curr_r]; front_pos++, front_swaps++);
        for (tail_pos = curr_r; tail_pos >= curr_l && s[tail_pos] != s[curr_l]; tail_pos--, tail_swaps++);

        if (front_swaps <= tail_swaps) {
            for (int i = front_pos - 1; i >= curr_l; i--) {
                std::swap(s[i], s[i + 1]);
            }
            total_swaps += front_swaps;
            st.push({curr_l + 1, curr_r - 1});
        } else {
            for (int i = tail_pos + 1; i <= curr_r; i++) {
                std::swap(s[i - 1], s[i]);
            }
            total_swaps += tail_swaps;
            st.push({curr_l + 1, curr_r - 1});
        }
    }

    return total_swaps;
}

